class TestProcessData:
    """测试 process_data 函数的单元测试类"""

    def setup_method(self):
        """每个测试方法前清除缓存"""
        process_data.cache_clear()

    # ==================== 正常用例 ====================

    def test_process_data_with_normal_dict(self):
        """测试正常字典数据处理"""
        data = {"name": "john", "city": "beijing"}
        result = process_data(data)
        assert result == {"name": "JOHN", "city": "BEIJING"}

    def test_process_data_with_mixed_case(self):
        """测试混合大小写的字典值"""
        data = {"key1": "PyThOn", "key2": "TeSt"}
        result = process_data(data)
        assert result == {"key1": "PYTHON", "key2": "TEST"}

    def test_process_data_with_already_uppercase(self):
        """测试已经是大写的字典值"""
        data = {"a": "HELLO", "b": "WORLD"}
        result = process_data(data)
        assert result == {"a": "HELLO", "b": "WORLD"}

    def test_process_data_returns_new_dict(self):
        """测试返回新字典而非修改原字典"""
        original = {"key": "value"}
        result = process_data(original)
        assert original["key"] == "value"  # 原字典未改变
        assert result["key"] == "VALUE"
        assert result is not original

    # ==================== 边界用例 ====================

    def test_process_data_with_empty_dict(self):
        """测试空字典"""
        data = {}
        result = process_data(data)
        assert result == {}

    def test_process_data_with_single_key(self):
        """测试单元素字典"""
        data = {"only": "one"}
        result = process_data(data)
        assert result == {"only": "ONE"}

    def test_process_data_with_numeric_values(self):
        """测试数字类型的值"""
        data = {"int_val": 123, "float_val": 45.67}
        result = process_data(data)
        assert result == {"int_val": "123", "float_val": "45.67"}
        assert result["int_val"] == "123"
        assert result["float_val"] == "45.67"

    def test_process_data_with_special_characters(self):
        """测试特殊字符"""
        data = {"sym": "!@#$%", "chinese": "你好"}
        result = process_data(data)
        assert result == {"sym": "!@#$%", "chinese": "你好"}

    def test_process_data_with_mixed_types(self):
        """测试混合类型值"""
        data = {
            "string": "hello",
            "number": 42,
            "float": 3.14,
            "none_val": None
        }
        result = process_data(data)
        assert result == {
            "string": "HELLO",
            "number": "42",
            "float": "3.14",
            "none_val": "NONE"
        }

    def test_process_data_with_whitespace(self):
        """测试包含空格的值"""
        data = {"space": "hello world", "tab": "a\tb"}
        result = process_data(data)
        assert result == {"space": "HELLO WORLD", "tab": "A\tB"}

    # ==================== 异常用例 ====================

    def test_process_data_with_invalid_type(self):
        """测试非字典类型输入"""
        with pytest.raises(AttributeError):
            process_data("string_input")

    def test_process_data_with_none(self):
        """测试 None 输入"""
        with pytest.raises(TypeError):
            process_data(None)

    def test_process_data_with_list(self):
        """测试列表输入应抛出异常"""
        with pytest.raises(AttributeError):
            process_data([("key", "value")])

    def test_process_data_with_uncached(self):
        """测试lru_cache未缓存相同结果"""
        data1 = {"a": "test"}
        data2 = {"a": "test"}

        result1 = process_data(data1)
        result2 = process_data(data2)

        # 相同输入应返回缓存结果
        assert result1 is result2
        assert result1 == result2


