class TestDataHandlerCache:
    """测试DataHandler的缓存机制"""

    def test_cache_miss_then_hit(self):
        """正常用例：缓存未命中后命中"""
        handler = DataHandler("test")

        call_count = 0
        def expensive_func():
            nonlocal call_count
            call_count += 1
            return "computed"

        result1 = handler._get_cached("key1", expensive_func)
        assert result1 == "computed"
        assert call_count == 1

        result2 = handler._get_cached("key1", expensive_func)
        assert result2 == "computed"
        assert call_count == 1  # 不再调用

    def test_cache_different_keys(self):
        """正常用例：不同key独立缓存"""
        handler = DataHandler("test")

        result1 = handler._get_cached("key1", lambda: 100)
        result2 = handler._get_cached("key2", lambda: 200)

        assert result1 == 100
        assert result2 == 200

    def test_cache_after_load(self):
        """异常用例：load后缓存应该清空"""
        handler = DataHandler("test")
        handler._get_cached("key", lambda: "value")
        assert "key" in handler._cache

        handler.load()
        assert "key" not in handler._cache


