        internal_data = handler.data
        internal_data["new_key"] = "new_value"
        assert handler.data["new_key"] == "new_value"

    def test_is_loaded_readonly(self):
        """正常用例：is_loaded只读"""
        handler = DataHandler("test")
        assert handler.is_loaded is False
        with pytest.raises(AttributeError):
            handler.is_loaded = True


class TestDataHandlerEdgeCases:
    """测试DataHandler边界情况"""

    def test_multiple_load_calls(self):
        """边界用例：多次load调用"""
        handler = DataHandler("test")
        handler.load()
        handler.load()
        assert handler.is_loaded is True

    def test_transform_before_load(self):
        """异常用例：未load就transform"""
        handler = DataHandler("test")
        result = handler.transform(str.upper)
        assert result == {}

    def test_very_long_source(self):
        """边界用例：非常长的source"""
        long_source = "x" * 10000
        handler = DataHandler(long_source)
        assert handler.source == long_source

    def test_transform_with_none_values(self):
        """边界用例：包含None值的转换"""
        handler = DataHandler("test")
        handler.load()
        handler._data = {"key": None}
        result = handler.transform(lambda x: str(x).upper())
        assert result == {"key": "NONE"}

